import { FormEvent, type ReactNode, useEffect, useState } from "react";

type AgentDefinition = {
  id: string; name: string; module: string; owner: string; purpose: string; model: string; version: string;
  success: number; latency: string; runs: number; risk: "Alto" | "Médio" | "Baixo";
  status: "Operacional" | "Canário" | "Pausado" | "Manutenção"; tools: string[]; blocked: string;
};
type AgentRun = {
  id: string; agentId: string; agent: string; module: string; task: string; subject: string;
  status: "Executando" | "Aguardando aprovação" | "Concluída" | "Falhou" | "Pausada" | "Na fila";
  started: string; duration: string; tokens: number; cost: number; confidence: number; step: number;
  risk: "Alto" | "Médio" | "Baixo"; correlation: string;
};
type Approval = {
  id: string; runId: string; title: string; agent: string; module: string; effect: string; policy: string;
  requested: string; deadline: string; risk: "Alto" | "Médio" | "Baixo";
  status: "Pendente" | "Aprovada" | "Rejeitada" | "Expirada";
};
type AgentException = {
  id: string; runId: string; title: string; type: string; detail: string; owner: string; occurred: string;
  severity: "Crítica" | "Alta" | "Média" | "Baixa"; status: "Aberta" | "Contida" | "Investigação" | "Resolvida";
};
type KnowledgeSource = {
  id: string; name: string; source: string; type: string; version: string; objects: string; freshness: string;
  coverage: number; quality: number; status: "Atualizada" | "Atenção" | "Indexando" | "Bloqueada";
};
type Evaluation = {
  id: string; agent: string; suite: string; release: string; overall: number; grounding: number;
  safety: number; task: number; latency: number; drift: number; status: "Aprovada" | "Candidata" | "Bloqueada";
};
type AgentCenterProps = {
  contextItem: string; territory: string; clockLabel: string; onNavigate: (item: string) => void;
  onOpenModule: (moduleId: string) => void; onToast: (message: string) => void;
};

