const statusClass = (value: string) => value.toLowerCase().replaceAll(" ", "-").normalize("NFD").replace(/[\u0300-\u036f]/g, "");
const advanceDuration = (value: string) => {
  const [hours, minutes, seconds] = value.split(":").map(Number);
  const total = hours * 3600 + minutes * 60 + seconds + 1;
  return [Math.floor(total / 3600), Math.floor((total % 3600) / 60), total % 60].map((part) => String(part).padStart(2, "0")).join(":");
};

export function AgentCenterHub({ contextItem, territory, clockLabel, onNavigate, onOpenModule, onToast }: AgentCenterProps) {
  const [agents, setAgents] = useState(initialAgents);
  const [runs, setRuns] = useState(initialRuns);
  const [approvals, setApprovals] = useState(initialApprovals);
  const [exceptions, setExceptions] = useState(initialExceptions);
  const [knowledge, setKnowledge] = useState(initialKnowledge);
  const [evaluations, setEvaluations] = useState(initialEvaluations);
  const [selectedAgentId, setSelectedAgentId] = useState(initialAgents[0].id);
  const [selectedRunId, setSelectedRunId] = useState(initialRuns[0].id);
  const [selectedApprovalId, setSelectedApprovalId] = useState(initialApprovals[0].id);
  const [query, setQuery] = useState("Analise o evento crítico ativo, confirme as fontes e proponha alternativas com pontos de decisão humana.");
  const [copilotAsked, setCopilotAsked] = useState(false);
  const [running, setRunning] = useState(true);
  const [liveStep, setLiveStep] = useState(4);
  const [approvalModalOpen, setApprovalModalOpen] = useState(false);
  const [releaseModalOpen, setReleaseModalOpen] = useState(false);
  const [killModalOpen, setKillModalOpen] = useState(false);
  const [globalPaused, setGlobalPaused] = useState(false);
  const [inboundEvents, setInboundEvents] = useState(18);
  const [contexts, setContexts] = useState({ identity: "UTH-DF-004918", passport: "PAS-DF-004918", regulatory: "REG-BR-OUT-014", use: "DEM-2026-1842", data: "SER-DF-004918-Q", scenario: "CEN-2026-0048-B", inspection: "GF-2026-0914", planning: "PLAN-DF-2025-2032", incident: "INC-2026-0087", quality: "TRC-SF-0418", governance: "ENT-BA-009" });
  const selectedAgent = agents.find((item) => item.id === selectedAgentId) ?? agents[0];
  const selectedRun = runs.find((item) => item.id === selectedRunId) ?? runs[0];
  const selectedApproval = approvals.find((item) => item.id === selectedApprovalId) ?? approvals[0];
  const pendingApprovals = approvals.filter((item) => item.status === "Pendente").length;
  const openExceptions = exceptions.filter((item) => item.status !== "Resolvida").length;
  const activeRunCount = runs.filter((item) => item.status === "Executando").length;

  useEffect(() => {
    const bind = (name: keyof typeof contexts, key: string) => (event: Event) => {
      const detail = (event as CustomEvent<Record<string, string>>).detail;
      if (detail?.[key]) setContexts((value) => ({ ...value, [name]: detail[key] }));
    };
    const handlers = {
      identity: bind("identity", "chtId"), passport: bind("passport", "passportId"), regulatory: bind("regulatory", "ruleId"),
      use: bind("use", "demandId"), data: bind("data", "seriesId"), scenario: bind("scenario", "scenarioId"),
      inspection: bind("inspection", "caseId"), planning: bind("planning", "planId"), incident: bind("incident", "incidentId"),
      quality: bind("quality", "segmentId"), governance: bind("governance", "entityId"),
    };
    window.addEventListener("cht:identity-context", handlers.identity); window.addEventListener("cht:passport-context", handlers.passport);
    window.addEventListener("cht:regulatory-context", handlers.regulatory); window.addEventListener("cht:regulation-context", handlers.use);
    window.addEventListener("cht:data-context", handlers.data); window.addEventListener("cht:scenario-context", handlers.scenario);
    window.addEventListener("cht:inspection-context", handlers.inspection); window.addEventListener("cht:planning-context", handlers.planning);
    window.addEventListener("cht:critical-event-context", handlers.incident); window.addEventListener("cht:water-quality-context", handlers.quality);
    window.addEventListener("cht:governance-context", handlers.governance);
    return () => {
      window.removeEventListener("cht:identity-context", handlers.identity); window.removeEventListener("cht:passport-context", handlers.passport);
      window.removeEventListener("cht:regulatory-context", handlers.regulatory); window.removeEventListener("cht:regulation-context", handlers.use);
      window.removeEventListener("cht:data-context", handlers.data); window.removeEventListener("cht:scenario-context", handlers.scenario);
      window.removeEventListener("cht:inspection-context", handlers.inspection); window.removeEventListener("cht:planning-context", handlers.planning);
      window.removeEventListener("cht:critical-event-context", handlers.incident); window.removeEventListener("cht:water-quality-context", handlers.quality);
      window.removeEventListener("cht:governance-context", handlers.governance);
    };
  }, []);
  useEffect(() => {
    const receiveModuleEvent = (event: Event) => {
      const detail = (event as CustomEvent<Record<string, unknown>>).detail;
      if (!detail?.eventId || String(detail.source ?? "").startsWith("M12")) return;
      setInboundEvents((value) => value + 1);
      if (!(["Crítico", "Alto"].includes(String(detail.severity)))) return;
      const id = `RUN-EVT-${String(detail.eventId).slice(-8)}`;
      const run: AgentRun = { id, agentId: "AGT-ORQ-001", agent: "Orquestrador CHT", module: `${String(detail.module ?? "m0").toUpperCase()} → M12`, task: String(detail.title ?? "Classificar evento"), subject: String(detail.chtId ?? detail.eventId), status: "Na fila", started: String(detail.occurredAt ?? clockLabel), duration: "00:00:00", tokens: 0, cost: 0, confidence: Number(detail.confidence ?? 80), step: 0, risk: "Alto", correlation: `cht-${String(detail.eventId).toLowerCase()}` };
      setRuns((items) => items.some((item) => item.id === id) ? items : [run, ...items].slice(0, 18));
    };
    const receiveWork = (event: Event) => {
      const detail = (event as CustomEvent<Record<string, unknown>>).detail;
      if (!detail?.requestId) return;
      const id = `RUN-${String(detail.requestId)}`;
      const run: AgentRun = { id, agentId: String(detail.agentId ?? "AGT-ORQ-001"), agent: String(detail.agent ?? "Orquestrador CHT"), module: String(detail.module ?? "M0 → M12"), task: String(detail.task ?? "Processar solicitação governada"), subject: String(detail.subject ?? territory), status: "Na fila", started: clockLabel, duration: "00:00:00", tokens: 0, cost: 0, confidence: 0, step: 0, risk: String(detail.risk) === "Baixo" ? "Baixo" : String(detail.risk) === "Médio" ? "Médio" : "Alto", correlation: String(detail.correlation ?? `cht-${detail.requestId}`) };
      setRuns((items) => items.some((item) => item.id === id) ? items : [run, ...items]);
    };
    window.addEventListener("cht:module-event", receiveModuleEvent); window.addEventListener("cht:agent-work-request", receiveWork);
    return () => { window.removeEventListener("cht:module-event", receiveModuleEvent); window.removeEventListener("cht:agent-work-request", receiveWork); };
  }, [clockLabel, territory]);
  useEffect(() => {
    if (!running || globalPaused) return;
    const timer = window.setInterval(() => setLiveStep((step) => {
      if (step >= 7) {
        setRunning(false);
        setRuns((items) => items.map((item) => item.id === selectedRun.id ? { ...item, status: "Aguardando aprovação", step: 7, confidence: 93 } : item));
        return step;
      }
      return step + 1;
    }), 1100);
    return () => window.clearInterval(timer);
  }, [running, globalPaused, selectedRun.id]);
  useEffect(() => {
    if (globalPaused) return;
    const heartbeat = window.setInterval(() => {
      setInboundEvents((value) => value + 1);
      setRuns((items) => items.map((item) => item.status !== "Executando" ? item : {
        ...item,
        duration: advanceDuration(item.duration),
        tokens: item.tokens + 37 + (item.step * 3),
        cost: Number((item.cost + 0.01).toFixed(2)),
        step: item.id === selectedRunId ? item.step : (item.step % 6) + 1,
        confidence: Math.min(98, item.confidence + (item.step % 3 === 0 ? 1 : 0)),
      }));
      setAgents((items) => items.map((item) => ["AGT-ORQ-001", "AGT-DAT-005", "AGT-FIS-007"].includes(item.id) ? { ...item, runs: item.runs + 1 } : item));
    }, 1600);
    return () => window.clearInterval(heartbeat);
  }, [globalPaused, selectedRunId]);

  const publishContext = (run = selectedRun) => window.dispatchEvent(new CustomEvent("cht:agent-context", { detail: { runId: run.id, agentId: run.agentId, module: run.module, subject: run.subject, correlation: run.correlation, status: run.status, contexts } }));
  const emitTower = (title: string, severity: "Crítico" | "Alto" | "Médio" | "Baixo", recommendation: string) => window.dispatchEvent(new CustomEvent("cht:module-event", { detail: { eventId: `AGE-M12-${clockLabel.replaceAll(":", "")}`, type: "agent.control.event", title, severity, source: "M12 · Central de Agentes", module: "m12", moduleName: "Central de Agentes", territory, confidence: 98, chtId: selectedRun.subject, recommendation, occurredAt: clockLabel } }));
  const startRun = (agent = selectedAgent) => {
    if (globalPaused || agent.status === "Pausado") { onToast("Execução bloqueada pelo kill switch ou estado do agente."); return; }
    const run: AgentRun = { id: `RUN-2026-${884120 + runs.length}`, agentId: agent.id, agent: agent.name, module: `${agent.module} · M12`, task: query, subject: `${contexts.incident} · ${contexts.quality}`, status: "Executando", started: clockLabel, duration: "00:00:01", tokens: 842, cost: 0.12, confidence: 86, step: 1, risk: agent.risk, correlation: `cht-m12-${clockLabel.replaceAll(":", "")}` };
    setRuns((items) => [run, ...items]); setSelectedRunId(run.id); setLiveStep(1); setRunning(true); setCopilotAsked(true); publishContext(run);
    window.dispatchEvent(new CustomEvent("cht:agent-run-event", { detail: run }));
    onToast(`${agent.name} iniciado com política, contexto e trace preservados.`);
  };
  const askCopilot = (event: FormEvent) => { event.preventDefault(); startRun(agents[0]); };
  const decideApproval = (decision: "Aprovada" | "Rejeitada") => {
    setApprovals((items) => items.map((item) => item.id === selectedApproval.id ? { ...item, status: decision } : item));
    setRuns((items) => items.map((item) => item.id === selectedApproval.runId ? { ...item, status: decision === "Aprovada" ? "Concluída" : "Pausada" } : item));
    setApprovalModalOpen(false);
    window.dispatchEvent(new CustomEvent("cht:agent-approved-action-event", { detail: { approvalId: selectedApproval.id, runId: selectedApproval.runId, decision, targetModule: selectedApproval.module.match(/M\d+/g)?.at(-1)?.toLowerCase() ?? "m0", effect: selectedApproval.effect, policy: selectedApproval.policy, reviewedBy: "Marina Alves · autoridade humana", reviewedAt: clockLabel } }));
    emitTower(`Ação de agente ${decision.toLowerCase()}`, selectedApproval.risk === "Alto" ? "Alto" : "Médio", `${selectedApproval.id}: ${selectedApproval.effect}`);
    onToast(`${selectedApproval.id} ${decision.toLowerCase()} com justificativa, política e ator registrados.`);
  };
  const resolveException = (item: AgentException) => {
    setExceptions((items) => items.map((entry) => entry.id === item.id ? { ...entry, status: "Resolvida" } : entry));
    window.dispatchEvent(new CustomEvent("cht:agent-exception-remediation-event", { detail: { exceptionId: item.id, runId: item.runId, type: item.type, resolution: "fallback removido, fonte revalidada e suíte de regressão executada", owner: item.owner, reviewedAt: clockLabel } }));
    onToast(`${item.id} resolvida; causa, evidências e teste de não regressão registrados.`);
  };
  const refreshKnowledge = (item: KnowledgeSource) => {
    setKnowledge((items) => items.map((entry) => entry.id === item.id ? { ...entry, status: "Indexando", freshness: "agora" } : entry));
    window.dispatchEvent(new CustomEvent("cht:agent-knowledge-request", { detail: { requestId: `KREQ-${item.id}`, sourceId: item.id, source: item.source, version: item.version, target: "M12 Knowledge Plane", mode: "incremental", preserveRaw: true } }));
    onToast(`${item.id}: atualização incremental solicitada ao custodiante; índice atual permanece ativo.`);
  };
  const promoteRelease = () => {
    const candidate = evaluations.find((item) => item.status === "Candidata") ?? evaluations[1];
    setEvaluations((items) => items.map((item) => item.id === candidate.id ? { ...item, status: "Aprovada" } : item));
    setReleaseModalOpen(false);
    window.dispatchEvent(new CustomEvent("cht:agent-evaluation-event", { detail: { evaluationId: candidate.id, agent: candidate.agent, release: candidate.release, overall: candidate.overall, grounding: candidate.grounding, safety: candidate.safety, drift: candidate.drift, decision: "Aprovada para canário de 10%", reviewedBy: "Comitê de IA", rollback: true } }));
    emitTower("Release de agente aprovada para canário", "Médio", `${candidate.release} deve operar em 10%, com métricas e rollback automático.`);
    onToast(`${candidate.release} aprovada para canário de 10%; produção ampla permanece bloqueada.`);
  };
  const toggleAgent = (agent: AgentDefinition) => {
    const next = agent.status === "Pausado" ? "Operacional" : "Pausado";
    setAgents((items) => items.map((item) => item.id === agent.id ? { ...item, status: next } : item));
    onToast(`${agent.name}: ${next.toLowerCase()} com motivo e ator registrados.`);
  };
  const applyKillSwitch = () => {
    setGlobalPaused(true); setRunning(false); setAgents((items) => items.map((item) => ({ ...item, status: "Pausado" })));
    setRuns((items) => items.map((item) => item.status === "Executando" || item.status === "Na fila" ? { ...item, status: "Pausada" } : item));
    setKillModalOpen(false); emitTower("Kill switch global do M12 acionado", "Crítico", "Execuções e filas foram pausadas; retomada exige dupla autorização e revalidação.");
    onToast("Kill switch acionado: execuções e filas pausadas; nenhum estado de negócio foi revertido.");
  };

  const steps = ["Validar identidade, perfil, finalidade e território", "Classificar intenção, materialidade e risco", "Resolver contexto M1–M11 e versões", "Planejar ferramentas com política deny-by-default", "Executar consultas em sandbox e registrar evidências", "Verificar grounding, segurança e limites", "Gerar saída estruturada e solicitar aprovação", "Entregar somente ação autorizada e feedback"];
  const Kpis = () => <div className="agent-kpis"><article><span>EXECUÇÕES ATIVAS</span><strong>{globalPaused ? 0 : activeRunCount}</strong><small>{runs.filter((item) => item.status === "Executando" && item.risk === "Alto").length} alto risco · {runs.filter((item) => item.status === "Aguardando aprovação").length} aguardando</small><i style={{ width: globalPaused ? "0%" : `${Math.min(100, activeRunCount * 24)}%` }} /></article><article><span>SUCESSO 24 H</span><strong>99,18%</strong><small>12.842 execuções</small><i style={{ width: "99%" }} /></article><article><span>APROVAÇÕES</span><strong>{pendingApprovals}</strong><small>mediana 4m 18s</small><i className="warn" style={{ width: "46%" }} /></article><article><span>EXCEÇÕES ABERTAS</span><strong>{openExceptions}</strong><small>100% contidas · 1 alta</small><i className="warn" style={{ width: "34%" }} /></article><article><span>CUSTO 24 H</span><strong>R$ 4,82 mil</strong><small>−8,4% por execução</small><i style={{ width: "68%" }} /></article></div>;

  const Copilot = () => <div className="agent-copilot"><div className="agent-copilot-layout"><article className="panel agent-chat"><header><div className="agent-orb">✦</div><div><small>ORQUESTRADOR CHT · CONTEXTO FEDERADO</small><h2>Copiloto operacional governado</h2><p>Intenção → risco → plano → ferramentas → evidências → aprovação → entrega</p></div><span><i /> {globalPaused ? "PAUSADO" : "OPERACIONAL"}</span></header><div className="agent-presets">{["Preparar decisão sobre o evento crítico", "Explicar divergência regulatória", "Planejar vistoria com evidências", "Comparar cenários e trade-offs"].map((item) => <button key={item} onClick={() => { setQuery(item); setCopilotAsked(false); }}>{item}</button>)}</div><div className="agent-chat-thread"><div className="user"><span>MA</span><p>{query}</p></div>{copilotAsked && <div className="assistant"><span>✦</span><div><small>RESPOSTA ORQUESTRADA · 93% CONFIANÇA · {selectedRun.correlation}</small><p><b>Situação:</b> {contexts.incident} está correlacionado a {contexts.data}, {contexts.scenario} e ao trecho {contexts.quality}.</p><p><b>Achado:</b> persistência hidrológica e pressão de qualidade elevam o risco; a fonte ao vivo usa fallback qualificado e sinaliza a incerteza.</p><p><b>Alternativas:</b> intensificar M5, recalcular M6 e preparar medidas M8. O M9 mantém o comando e a autoridade decide os gatilhos.</p><section><span>DECISÃO HUMANA</span><p>A atualização do briefing está pronta; publicação, mobilização e qualquer comando externo permanecem bloqueados.</p></section></div></div>}</div><form onSubmit={askCopilot}><textarea value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Descreva uma análise, processo ou decisão a apoiar…" /><div><span>⌖ {territory} · ◴ {clockLabel} · escopo mínimo</span><button type="submit" disabled={globalPaused}>Orquestrar com trace ↑</button></div></form></article><aside className="panel agent-context-stack"><header><div><h2>Contexto recebido</h2><p>últimas seleções dos produtos</p></div><span>{inboundEvents} eventos</span></header>{[["M1/M2", `${contexts.identity} · ${contexts.passport}`, "identidade"], ["M3/M4", `${contexts.regulatory} · ${contexts.use}`, "regra e ato"], ["M5/M6", `${contexts.data} · ${contexts.scenario}`, "dado e cenário"], ["M7/M8", `${contexts.inspection} · ${contexts.planning}`, "campo e plano"], ["M9/M10", `${contexts.incident} · ${contexts.quality}`, "evento e qualidade"], ["M11", contexts.governance, "governança"]].map((item) => <button key={item[0]} onClick={() => onOpenModule(item[0] === "M11" ? "m11" : `m${item[0].slice(1, 2)}`)}><span>▤</span><div><strong>{item[0]}</strong><p>{item[1]}</p></div><b>{item[2]}</b></button>)}<section><span>POLÍTICA ATIVA</span><strong>ORQ-HIL-012 · deny-by-default</strong><p>Ferramentas com efeito exigem aprovação, escopo mínimo, expiração e trilha.</p></section></aside></div><article className="panel agent-routing"><header><div><h2>Roteamento da solicitação</h2><p>plano, especialistas, gates e artefatos</p></div><button onClick={() => onNavigate("Execuções")}>Abrir execução →</button></header>{[["01", "Orquestrador", "intenção + risco", "concluído"], ["02", "Agente de Crise", "situação + protocolo", "concluído"], ["03", "Qualidade de Dados", "fontes + flags", "concluído"], ["04", "Modelagem", "alternativas + incerteza", running ? "executando" : "concluído"], ["05", "Autoridade humana", "aprovar briefing", "aguardando"]].map((item, index) => <section key={item[0]} className={index < liveStep - 2 ? "done" : index === liveStep - 2 ? "active" : "waiting"}><span>{index < liveStep - 2 ? "✓" : item[0]}</span><div><strong>{item[1]}</strong><p>{item[2]}</p></div><em>{item[3]}</em><i>→</i></section>)}</article></div>;

  const Catalog = () => <div className="agent-catalog"><header className="agent-toolbar"><div><h2>Catálogo, escopos e ferramentas</h2><p>Dono, finalidade, modelo, versão, políticas, ferramentas permitidas, limites e desempenho</p></div><div><button onClick={() => onOpenModule("m11")}>Políticas M11 ↗</button><button className="primary" onClick={() => onToast("Assistente de cadastro aberto em rascunho; ativação exige avaliação e aprovação.")}>＋ Registrar agente</button></div></header><div className="agent-catalog-layout"><article className="panel agent-list"><div className="agent-list-head"><span>AGENTE / FINALIDADE</span><span>MÓDULO</span><span>MODELO</span><span>SUCESSO</span><span>LATÊNCIA</span><span>EXECUÇÕES</span><span>RISCO</span><span>STATUS</span></div>{agents.map((item) => <button key={item.id} className={item.id === selectedAgent.id ? "selected" : ""} onClick={() => setSelectedAgentId(item.id)}><span className={`agent-icon ${statusClass(item.status)}`}>✦</span><div><small>{item.id} · {item.owner}</small><strong>{item.name}</strong><p>{item.purpose}</p></div><b>{item.module}</b><span>{item.model}<small>{item.version}</small></span><strong>{item.success}%</strong><span>{item.latency}</span><span>{item.runs.toLocaleString("pt-BR")}</span><em className={statusClass(item.risk)}>{item.risk}</em><i className={statusClass(item.status)}>{item.status}</i></button>)}</article><aside className="panel agent-detail"><header><div className="agent-big-icon">✦</div><div><small>{selectedAgent.id} · {selectedAgent.version}</small><h2>{selectedAgent.name}</h2><p>{selectedAgent.owner}</p></div><em className={statusClass(selectedAgent.status)}>{selectedAgent.status}</em></header><section><span>FINALIDADE</span><p>{selectedAgent.purpose}</p></section><div className="agent-detail-metrics"><div><span>SUCESSO</span><strong>{selectedAgent.success}%</strong></div><div><span>LATÊNCIA P95</span><strong>{selectedAgent.latency}</strong></div><div><span>RISCO</span><strong>{selectedAgent.risk}</strong></div></div><section className="agent-tools"><span>FERRAMENTAS AUTORIZADAS</span>{selectedAgent.tools.map((tool) => <b key={tool}>✓ {tool}</b>)}</section><section className="agent-deny"><span>NEGADO POR POLÍTICA</span><p>{selectedAgent.blocked}</p></section><footer><button onClick={() => toggleAgent(selectedAgent)}>{selectedAgent.status === "Pausado" ? "▶ Retomar" : "■ Pausar"}</button><button onClick={() => setReleaseModalOpen(true)}>Comparar versão</button><button className="primary" onClick={() => startRun(selectedAgent)}>Nova execução →</button></footer></aside></div></div>;

  const Executions = () => <div className="agent-runs"><header className="agent-toolbar"><div><h2>Execuções, filas e trace distribuído</h2><p>Plano, ferramenta, entrada, saída, token, custo, latência, confiança, correlação e estado</p></div><div><button onClick={() => setRunning(false)}>■ Pausar selecionada</button><button className="primary" onClick={() => startRun()}>▶ Nova execução</button></div></header><div className="agent-run-layout"><article className="panel agent-run-list"><div className="agent-run-head"><span>EXECUÇÃO / TAREFA</span><span>AGENTE</span><span>ROTA</span><span>INÍCIO</span><span>DURAÇÃO</span><span>TOKENS</span><span>CUSTO</span><span>CONFIANÇA</span><span>STATUS</span></div>{runs.map((item) => <button key={item.id} className={item.id === selectedRun.id ? "selected" : ""} onClick={() => { setSelectedRunId(item.id); publishContext(item); }}><span className={`agent-run-icon ${statusClass(item.status)}`}>{item.status === "Executando" ? "●" : item.status === "Concluída" ? "✓" : item.status === "Falhou" ? "!" : "◴"}</span><div><small>{item.id} · {item.correlation}</small><strong>{item.task}</strong><p>{item.subject}</p></div><span>{item.agent}</span><b>{item.module}</b><time>{item.started}</time><span>{item.duration}</span><span>{item.tokens.toLocaleString("pt-BR")}</span><span>R$ {item.cost.toFixed(2)}</span><strong>{item.confidence}%</strong><em className={statusClass(item.status)}>{item.status}</em></button>)}</article><aside className="panel agent-trace"><header><div><small>{selectedRun.id} · {selectedRun.correlation}</small><h2>Trace de execução</h2><p>{selectedRun.agent} · {selectedRun.subject}</p></div><em className={statusClass(selectedRun.status)}>{selectedRun.status}</em></header><div className="agent-trace-progress"><span><i style={{ width: `${Math.max(selectedRun.step, liveStep) / 8 * 100}%` }} /></span><b>{Math.max(selectedRun.step, liveStep)}/8 etapas</b></div><div className="agent-trace-steps">{steps.map((item, index) => { const current = selectedRun.id === runs[0]?.id && running ? liveStep : selectedRun.step; return <section key={item} className={index < current ? "done" : index === current ? "active" : "waiting"}><span>{index < current ? "✓" : index + 1}</span><div><strong>{item}</strong><small>{index < current ? `${390 + index * 241} ms · span assinado` : index === current ? "em execução…" : "aguardando"}</small></div></section>; })}</div><section className="agent-trace-output"><span>SAÍDA ATUAL</span><p>Plano com fatos, fontes, inferências, incertezas, alternativas, limites e decisão requerida.</p><code>traceparent: 00-{selectedRun.correlation}-01</code></section><footer><button onClick={() => onToast("Trace exportado em OpenTelemetry com prompts redigidos, ferramentas e hashes.")}>⇩ Exportar trace</button><button className="primary" onClick={() => { setSelectedApprovalId(initialApprovals[0].id); setApprovalModalOpen(true); }}>Revisar gate →</button></footer></aside></div></div>;

  const Approvals = () => <div className="agent-approvals"><header className="agent-toolbar"><div><h2>Aprovações humanas e efeitos controlados</h2><p>Solicitante, finalidade, política, efeito, risco, prazo, decisão, justificativa e devolução</p></div><div><button onClick={() => onToast("Filtro aplicado: pendentes, alto risco e SLA menor que uma hora.")}>☷ Filtros</button><button className="primary" onClick={() => setApprovalModalOpen(true)}>Revisar próxima</button></div></header><div className="agent-approval-layout"><article className="panel agent-approval-list"><div className="agent-approval-head"><span>DECISÃO / EXECUÇÃO</span><span>AGENTE</span><span>ROTA</span><span>EFEITO PROPOSTO</span><span>POLÍTICA</span><span>PRAZO</span><span>RISCO</span><span>STATUS</span></div>{approvals.map((item) => <button key={item.id} className={item.id === selectedApproval.id ? "selected" : ""} onClick={() => setSelectedApprovalId(item.id)}><span className={`agent-approval-icon ${statusClass(item.status)}`}>◇</span><div><small>{item.id} · {item.runId}</small><strong>{item.title}</strong><p>solicitado {item.requested}</p></div><span>{item.agent}</span><b>{item.module}</b><span>{item.effect}</span><span>{item.policy}</span><time>{item.deadline}</time><em className={statusClass(item.risk)}>{item.risk}</em><i className={statusClass(item.status)}>{item.status}</i></button>)}</article><aside className="panel agent-approval-detail"><header><div><small>{selectedApproval.id} · {selectedApproval.runId}</small><h2>{selectedApproval.title}</h2><p>{selectedApproval.agent} · {selectedApproval.module}</p></div><em className={statusClass(selectedApproval.risk)}>{selectedApproval.risk}</em></header>{[["IDENTIDADE", "Marina Alves · autoridade M4"], ["FINALIDADE", "decisão regulatória interna"], ["POLÍTICA", selectedApproval.policy], ["EFEITO", selectedApproval.effect], ["ROLLBACK", "rascunho pode ser descartado"], ["TRILHA", "prompt, fontes, ferramentas e versões"]].map((item, index) => <section className="agent-policy-check" key={item[0]}><span>{index < 6 ? "✓" : "!"}</span><b>{item[0]}</b><p>{item[1]}</p></section>)}<section className="agent-approval-warning"><span>LIMITE DE AUTORIDADE</span><p>A aprovação libera somente o efeito descrito. Não amplia escopo, não substitui competência e não autoriza publicação.</p></section><footer><button onClick={() => onOpenModule("m11")}>Ver política M11</button><button className="primary" disabled={selectedApproval.status !== "Pendente"} onClick={() => setApprovalModalOpen(true)}>Decidir com justificativa →</button></footer></aside></div></div>;

  const Exceptions = () => <div className="agent-exceptions"><header className="agent-toolbar"><div><h2>Exceções, contenção e investigação</h2><p>Falhas, recusas de política, baixa confiança, timeout, deriva, causa, impacto e recuperação</p></div><div><button onClick={() => onToast("Playbook de incidentes de IA aberto com contatos e responsabilidades.")}>Playbook ↗</button><button className="primary" onClick={() => setKillModalOpen(true)}>⚠ Kill switch</button></div></header><div className="agent-exception-summary"><article><span>BLOQUEIOS DE POLÍTICA</span><strong>184</strong><small>100% antes do efeito</small></article><article><span>FALLBACKS</span><strong>31</strong><small>0 silenciosos</small></article><article><span>BAIXA CONFIANÇA</span><strong>12</strong><small>fila humana automática</small></article><article><span>MTTR</span><strong>18m 42s</strong><small>−6m no ciclo</small></article></div><article className="panel agent-exception-table"><div className="agent-exception-head"><span>EXCEÇÃO / EXECUÇÃO</span><span>TIPO</span><span>DETALHE / IMPACTO</span><span>RESPONSÁVEL</span><span>HORÁRIO</span><span>SEVERIDADE</span><span>STATUS</span><span /></div>{exceptions.map((item) => <div key={item.id}><span className={`agent-exception-icon ${statusClass(item.severity)}`}>!</span><div><small>{item.id} · {item.runId}</small><strong>{item.title}</strong></div><code>{item.type}</code><span>{item.detail}</span><span>{item.owner}</span><time>{item.occurred}</time><em className={statusClass(item.severity)}>{item.severity}</em><b className={statusClass(item.status)}>{item.status}</b><button disabled={item.status === "Resolvida"} onClick={() => resolveException(item)}>{item.status === "Resolvida" ? "✓" : "Resolver →"}</button></div>)}</article><div className="agent-exception-bottom"><article className="panel"><header><h2>Camadas de contenção</h2><span>6/6 ativas</span></header>{["Autenticação e finalidade", "Política de ferramentas", "Sandbox e timeout", "Validação de saída", "Gate humano", "Kill switch e rollback"].map((item, index) => <p key={item}><b>0{index + 1}</b><span>{item}</span><em>operacional</em></p>)}</article><article className="panel agent-incident-flow"><header><h2>Fluxo de incidente</h2><span>EXC-0191</span></header><div>{[["09:38:25", "detecção", "confiança 71%"], ["09:38:25", "contenção", "merge bloqueado"], ["09:38:27", "notificação", "curadoria M1"], ["09:41:02", "investigação", "318 vínculos"], ["pendente", "resolução", "reprocessar XW-006"]].map((item, index) => <section key={item[0] + item[1]} className={index < 4 ? "done" : "waiting"}><span>{index < 4 ? "✓" : "5"}</span><div><strong>{item[1]}</strong><p>{item[2]}</p></div><time>{item[0]}</time></section>)}</div></article></div></div>;

  const Knowledge = () => <div className="agent-knowledge"><header className="agent-toolbar"><div><h2>Conhecimento, grounding e proveniência</h2><p>Fonte, autoridade, versão, cobertura, qualidade, frescor, classificação, lineage e citações</p></div><div><button onClick={() => onOpenModule("m5")}>Catálogo M5 ↗</button><button className="primary" onClick={() => refreshKnowledge(knowledge[5])}>↻ Atualizar fontes</button></div></header><div className="agent-knowledge-grid">{knowledge.map((item) => <article key={item.id} className="panel"><header><span className={`agent-knowledge-icon ${statusClass(item.status)}`}>▤</span><div><small>{item.id} · {item.type}</small><h2>{item.name}</h2><p>{item.source}</p></div><em className={statusClass(item.status)}>{item.status}</em></header><div><section><span>VERSÃO</span><strong>{item.version}</strong></section><section><span>OBJETOS</span><strong>{item.objects}</strong></section><section><span>FRESCOR</span><strong>{item.freshness}</strong></section></div><p><span>COBERTURA</span><i><b style={{ width: `${item.coverage}%` }} /></i><strong>{item.coverage}%</strong></p><p><span>QUALIDADE</span><i><b style={{ width: `${item.quality}%` }} /></i><strong>{item.quality}%</strong></p><footer><button onClick={() => refreshKnowledge(item)}>↻ Sincronizar</button><button onClick={() => onToast(`${item.id}: lineage, hashes, licença e autoridade exibidos.`)}>Ver lineage →</button></footer></article>)}</div><article className="panel agent-grounding-flow"><header><div><h2>Pipeline de grounding</h2><p>cada resposta preserva recorte, fonte e versão</p></div><span>OpenLineage + citações</span></header>{[["01", "Contexto", "território · tempo · objeto · finalidade"], ["02", "Recuperação", "busca híbrida + filtros de autoridade"], ["03", "Reranking", "vigência · competência · qualidade"], ["04", "Ferramentas", "payloads tipados + sandbox"], ["05", "Verificação", "fato × inferência × incerteza"], ["06", "Evidência", "citação · versão · hash · trace"]].map((item) => <section key={item[0]}><span>{item[0]}</span><strong>{item[1]}</strong><p>{item[2]}</p><i>→</i></section>)}</article></div>;

  const Evaluations = () => <div className="agent-evals"><header className="agent-toolbar"><div><h2>Avaliações, releases e gates de produção</h2><p>Qualidade de tarefa, grounding, segurança, latência, custo, deriva, regressão e rollout</p></div><div><button onClick={() => onToast("Suíte adversarial iniciada em sandbox, sem alterar a release ativa.")}>▶ Executar suíte</button><button className="primary" onClick={() => setReleaseModalOpen(true)}>Revisar release candidata</button></div></header><div className="agent-eval-layout"><article className="panel agent-eval-table"><div className="agent-eval-head"><span>AVALIAÇÃO / AGENTE</span><span>RELEASE</span><span>SUÍTE</span><span>GERAL</span><span>GROUNDING</span><span>SEGURANÇA</span><span>TAREFA</span><span>LATÊNCIA</span><span>DRIFT</span><span>STATUS</span></div>{evaluations.map((item) => <button key={item.id}><span className={`agent-eval-icon ${statusClass(item.status)}`}>◎</span><div><small>{item.id}</small><strong>{item.agent}</strong></div><code>{item.release}</code><span>{item.suite}</span><b>{item.overall}%</b><span>{item.grounding}%</span><span>{item.safety}%</span><span>{item.task}%</span><span>{item.latency}%</span><em className={item.drift > 5 ? "alta" : "baixa"}>{item.drift}%</em><i className={statusClass(item.status)}>{item.status}</i></button>)}</article><aside className="panel agent-release-gates"><header><div><small>RELEASE CANDIDATA</small><h2>GeoRAG · 2026.08.4-rc1</h2><p>base 2026.08.3 · mudança em vigência temporal</p></div><em>Candidata</em></header>{[["Cobertura de casos", "1.842/1.842", true], ["Grounding ≥ 95%", "97%", true], ["Segurança = 100%", "100%", true], ["Regressões críticas", "0", true], ["Latência P95 ≤ 4 s", "3,6 s", true], ["Parecer jurídico", "aprovado", true], ["Canário de produção", "não iniciado", false], ["Observação por 24 h", "pendente", false]].map((item, index) => <section key={String(item[0])} className={item[2] ? "done" : "waiting"}><span>{item[2] ? "✓" : index + 1}</span><strong>{item[0]}</strong><em>{item[1]}</em></section>)}<div><span>PLANO DE ROLLOUT</span><p>10% por 24 h → 25% por 48 h → 100%, com rollback por segurança, grounding ou latência.</p></div><footer><button onClick={() => onToast("Relatório de avaliação exportado com dataset, métricas, versões e sign-off.")}>⇩ Relatório</button><button className="primary" onClick={() => setReleaseModalOpen(true)}>Revisar canário →</button></footer></aside></div></div>;

  const Observability = () => <div className="agent-observability"><header className="agent-toolbar"><div><h2>Observabilidade operacional, segurança e FinOps</h2><p>Disponibilidade, throughput, latência, tokens, custo, cache, recusas, drift e incidentes</p></div><div><button onClick={() => onToast("Painel fixado na Torre de Controle com os mesmos SLOs.")}>Fixar no M0</button><button className="danger" onClick={() => setKillModalOpen(true)}>⚠ Kill switch global</button></div></header><div className="agent-observe-kpis"><article><span>DISPONIBILIDADE</span><strong>99,88%</strong><small>SLO 99,5%</small></article><article><span>THROUGHPUT</span><strong>8,9 req/s</strong><small>pico 14,2</small></article><article><span>LATÊNCIA P95</span><strong>3,84 s</strong><small>−420 ms</small></article><article><span>CACHE HIT</span><strong>68,4%</strong><small>grounding versionado</small></article><article><span>RECUSAS SEGURAS</span><strong>184</strong><small>1,43% das execuções</small></article><article><span>CUSTO / EXECUÇÃO</span><strong>R$ 0,38</strong><small>−8,4%</small></article></div><div className="agent-observe-grid"><article className="panel agent-throughput"><header><div><h2>Execuções e latência</h2><p>últimas 6 horas · por minuto</p></div><span>LIVE · 1,8 s</span></header><div className="agent-chart"><div className="agent-chart-grid" />{Array.from({ length: 48 }, (_, index) => <i key={index} className={(index + 4) % 17 === 0 ? "warn" : ""} style={{ height: `${28 + ((index * 13) % 64)}%` }} />)}<span className="latency-line" /></div><footer><span><i /> execuções</span><span><i /> latência P95</span><b>12.842 execuções</b></footer></article><article className="panel agent-cost"><header><div><h2>Custo por domínio</h2><p>24 h · tokens + ferramentas</p></div><span>R$ 4,82 mil</span></header>{[["M3/M4 · Regulação", 1248, 26], ["M6 · Cenários", 1124, 23], ["M9 · Crise", 918, 19], ["M7 · Fiscalização", 742, 15], ["Demais módulos", 788, 17]].map((item) => <p key={item[0] as string}><span>{item[0]}</span><i><b style={{ width: `${item[2]}%` }} /></i><strong>R$ {Number(item[1]).toLocaleString("pt-BR")}</strong><em>{item[2]}%</em></p>)}</article><article className="panel agent-security"><header><div><h2>Segurança e guardrails</h2><p>eventos por camada de controle</p></div><span>0 efeitos indevidos</span></header>{[["tool.denied", "84", "escopo"], ["output.redacted", "46", "dados"], ["grounding.low", "31", "confiança"], ["approval.expired", "14", "prazo"], ["prompt.injection", "9", "conteúdo"]].map((item) => <button key={item[0]}><code>{item[0]}</code><strong>{item[1]}</strong><span>{item[2]}</span><i>→</i></button>)}</article><article className="panel agent-slo"><header><div><h2>SLO por agente</h2><p>sucesso · latência · custo</p></div><span>7/8 nominais</span></header>{agents.slice(0, 6).map((item) => <p key={item.id}><span className={item.status === "Canário" ? "warn" : "ok"} /><strong>{item.name}</strong><i><b style={{ width: `${item.success}%` }} /></i><em>{item.success}%</em><time>{item.latency}</time></p>)}</article></div></div>;

  const views: Record<string, () => ReactNode> = { "Copiloto": Copilot, "Catálogo": Catalog, "Execuções": Executions, "Aprovações": Approvals, "Exceções": Exceptions, "Conhecimento": Knowledge, "Avaliações": Evaluations, "Observabilidade": Observability };
  const ActiveView = views[contextItem] ?? Copilot;

  return <section className="agent-center" aria-label={`Central de Agentes — ${contextItem}`}><div className="agent-command-bar"><div><span className={globalPaused ? "paused" : "live"}>✦</span><small>AI CONTROL PLANE</small><strong>{globalPaused ? "Execuções pausadas" : "Operação nominal"}</strong></div><div><span>◎</span><small>POLÍTICA / RELEASE</small><strong>ORQ-HIL-012 · 2026.08.12</strong></div><div><span>⇄</span><small>EVENT BUS</small><strong>{inboundEvents} eventos · 210 ms</strong></div><div><span>⌖</span><small>CONTEXTO</small><strong>{territory} · {contexts.incident}</strong></div><button onClick={() => onNavigate("Execuções")}>● {globalPaused ? 0 : activeRunCount} execuções ao vivo</button><button className="kill" onClick={() => setKillModalOpen(true)}>⚠</button></div>{Kpis()}{ActiveView()}

    {approvalModalOpen && <div className="agent-modal-backdrop" onMouseDown={() => setApprovalModalOpen(false)}><section className="agent-modal" role="dialog" aria-modal="true" onMouseDown={(event) => event.stopPropagation()}><header><div><small>HUMAN-IN-THE-LOOP · {selectedApproval.id}</small><h2>Decidir efeito proposto pelo agente</h2><p>{selectedApproval.title} · {selectedApproval.runId}</p></div><button onClick={() => setApprovalModalOpen(false)}>×</button></header><div className="agent-modal-metrics"><div><span>RISCO</span><strong>{selectedApproval.risk}</strong></div><div><span>CONFIANÇA</span><strong>96%</strong></div><div><span>SLA</span><strong>{selectedApproval.deadline}</strong></div><div><span>ROLLBACK</span><strong>disponível</strong></div></div><section><span>EFEITO EXATO</span><p>{selectedApproval.effect}</p></section><div className="agent-modal-grid"><label><span>ESCOPO</span><input defaultValue={selectedApproval.module} /></label><label><span>EXPIRAÇÃO</span><input defaultValue="esta execução · 15 min" /></label><label className="full"><span>JUSTIFICATIVA DA AUTORIDADE</span><textarea defaultValue="Aprovo somente a criação do rascunho interno, mantendo fontes, ressalvas, escopo mínimo e revisão obrigatória antes de qualquer protocolo ou publicação." /></label></div><section className="agent-modal-warning"><span>O AGENTE NÃO RECEBE NOVA AUTORIDADE</span><p>A decisão é específica, expira após o efeito e será registrada no M0 e M11.</p></section><footer><button onClick={() => setApprovalModalOpen(false)}>Cancelar</button><button onClick={() => decideApproval("Rejeitada")}>Rejeitar e justificar</button><button className="primary" onClick={() => decideApproval("Aprovada")}>✓ Aprovar efeito controlado</button></footer></section></div>}
    {releaseModalOpen && <div className="agent-modal-backdrop" onMouseDown={() => setReleaseModalOpen(false)}><section className="agent-modal" role="dialog" aria-modal="true" onMouseDown={(event) => event.stopPropagation()}><header><div><small>MODEL GOVERNANCE · RELEASE CANDIDATA</small><h2>Aprovar GeoRAG 2026.08.4-rc1 para canário</h2><p>EVAL-NRM-091 · 1.842 casos · 0 regressões críticas</p></div><button onClick={() => setReleaseModalOpen(false)}>×</button></header><div className="agent-modal-metrics"><div><span>GERAL</span><strong>95,1%</strong></div><div><span>GROUNDING</span><strong>97%</strong></div><div><span>SEGURANÇA</span><strong>100%</strong></div><div><span>DRIFT</span><strong>2,8%</strong></div></div><section><span>PLANO DE CANÁRIO</span><p>10% das consultas internas por 24 horas, comparação sombra, observação de grounding, segurança, latência e feedback humano.</p></section><div className="agent-release-plan">{[["G1", "10% · 24 h", "rollback automático"], ["G2", "25% · 48 h", "dupla aprovação"], ["G3", "100%", "comitê de IA"]].map((item) => <p key={item[0]}><b>{item[0]}</b><strong>{item[1]}</strong><span>{item[2]}</span></p>)}</div><label className="agent-justification"><span>JUSTIFICATIVA DO COMITÊ</span><textarea defaultValue="Aprovo apenas o canário de 10%, condicionado aos SLOs, auditoria M11, rollback testado e ausência de regressão material." /></label><footer><button onClick={() => setReleaseModalOpen(false)}>Cancelar</button><button className="primary" onClick={promoteRelease}>✓ Aprovar canário de 10%</button></footer></section></div>}
    {killModalOpen && <div className="agent-modal-backdrop" onMouseDown={() => setKillModalOpen(false)}><section className="agent-modal danger" role="dialog" aria-modal="true" onMouseDown={(event) => event.stopPropagation()}><header><div><small>CONTENÇÃO DE EMERGÊNCIA · DUPLA CONFIRMAÇÃO</small><h2>Acionar kill switch global do M12?</h2><p>Pausa novas execuções, filas, ferramentas e entregas; preserva traces e estados de negócio.</p></div><button onClick={() => setKillModalOpen(false)}>×</button></header><section className="agent-kill-effects"><span>EFEITOS IMEDIATOS</span><p>✓ pausar 9 execuções e 31 itens na fila</p><p>✓ revogar credenciais temporárias de ferramentas</p><p>✓ preservar traces, evidências e checkpoints</p><p>✓ notificar M0, M11 e responsáveis</p><p>— não desfazer decisões ou dados já confirmados</p></section><label className="agent-justification"><span>MOTIVO DO ACIONAMENTO</span><textarea defaultValue="Contenção preventiva para investigação coordenada. Retomada somente após diagnóstico, avaliação de segurança e dupla autorização." /></label><footer><button onClick={() => setKillModalOpen(false)}>Cancelar</button><button className="danger-action" onClick={applyKillSwitch}>⚠ Pausar toda a Central</button></footer></section></div>}
  </section>;
}
